const processBillingCycles = `-- name: ProcessBillingCycles :many
WITH inserted_cycles AS (
    INSERT INTO billing_cycles (
        card_number,
        cycle_start,
        cycle_end,
        amount_due,
        due_date,
        status
    )
    SELECT
        c.card_number,
        date_trunc('month', CURRENT_DATE),
        date_trunc('month', CURRENT_DATE) + interval '1 month' - interval '1 day',
        c.outstanding_balance,
        CURRENT_DATE,
        'unpaid'
    FROM cards c
    WHERE c.card_type = 'credit'
      AND c.status = 'active'
      AND c.deleted_at IS NULL
      AND c.outstanding_balance > 0
      AND $1 BETWEEN 1 AND 31
      AND EXTRACT(DAY FROM CURRENT_DATE) = $1
    ON CONFLICT (card_number, cycle_start, cycle_end) DO NOTHING
    RETURNING billing_id, card_number, cycle_start, cycle_end, amount_due, due_date, status, created_at, updated_at
), queued_events AS (
    INSERT INTO outbox_events (event_key, topic, message_key, payload)
    SELECT
        'card-statement:' || billing_id::text,
        'card.statement.generated',
        billing_id::text,
        jsonb_build_object(
            'billing_id', billing_id,
            'card_number', card_number,
            'billing_cycle_day', $1,
            'cycle_start', cycle_start,
            'cycle_end', cycle_end,
            'amount_due', amount_due
        )
    FROM inserted_cycles
    ON CONFLICT (event_key) DO NOTHING
    RETURNING event_key
)
SELECT
    billing_id,
    card_number,
    cycle_start,
    cycle_end,
    amount_due,
    due_date,
    status,
    created_at,
    updated_at
FROM inserted_cycles
`

type ProcessBillingCyclesRow struct {
	BillingID  int32            `json:"billing_id"`
	CardNumber string           `json:"card_number"`
	CycleStart time.Time        `json:"cycle_start"`
	CycleEnd   time.Time        `json:"cycle_end"`
	AmountDue  int32            `json:"amount_due"`
	DueDate    time.Time        `json:"due_date"`
	Status     string           `json:"status"`
	CreatedAt  pgtype.Timestamp `json:"created_at"`
	UpdatedAt  pgtype.Timestamp `json:"updated_at"`
}

// ProcessBillingCycles: Creates the current-month statement for credit cards
// with an outstanding balance. The period unique index makes retries safe.
func (q *Queries) ProcessBillingCycles(ctx context.Context, dollar_1 interface{}) ([]*ProcessBillingCyclesRow, error) {
	rows, err := q.db.Query(ctx, processBillingCycles, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ProcessBillingCyclesRow
	for rows.Next() {
		var i ProcessBillingCyclesRow
		if err := rows.Scan(
			&i.BillingID,
			&i.CardNumber,
			&i.CycleStart,
			&i.CycleEnd,
			&i.AmountDue,
			&i.DueDate,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

